def numberOfSubarrays(nums, k):
    count = 0
    prefix = {0: 1}
    odds = 0
    for num in nums:
        if num % 2 == 1:
            odds += 1
        if odds - k in prefix:
            count += prefix[odds - k]
        prefix[odds] = prefix.get(odds, 0) + 1
    return count
